steps.starter_content:
server {
    listen 443 ssl;
    server_name shop.example.com;

    ssl_certificate     /etc/letsencrypt/live/shop.example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/shop.example.com/privkey.pem;
    ssl_protocols TLSv1 TLSv1.1 TLSv1.2;
    server_tokens on;

    location / {
        proxy_pass http://127.0.0.1:8000;
    }

    location /login {
        proxy_pass http://127.0.0.1:8000;
    }

    location /admin/ {
        proxy_pass http://127.0.0.1:8000;
    }

    location /uploads/ {
        root /var/www/shop;
        autoindex on;
    }
}

steps.prompt:
Edit shop-secure.conf:

(1) Above the server block, define a rate-limit zone:
    limit_req_zone $binary_remote_addr zone=login:10m rate=5r/m;
(2) Allow only modern TLS: ssl_protocols TLSv1.2 TLSv1.3;
(3) Stop advertising the nginx version: server_tokens off;
(4) In the server block, add HSTS:
    add_header Strict-Transport-Security "max-age=31536000" always;
(5) In the server block, cap request bodies: client_max_body_size 10m;
(6) In location /login, apply the zone and return 429 when it trips:
    limit_req zone=login burst=5 nodelay;
    limit_req_status 429;
(7) In location /admin/, permit only the office network 10.20.0.0/16 and refuse everyone else.
(8) In location /uploads/, remove the directory listing.

Leave every proxy_pass as it is.

steps.solution:
limit_req_zone $binary_remote_addr zone=login:10m rate=5r/m;

server {
    listen 443 ssl;
    server_name shop.example.com;

    ssl_certificate     /etc/letsencrypt/live/shop.example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/shop.example.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    server_tokens off;

    add_header Strict-Transport-Security "max-age=31536000" always;
    client_max_body_size 10m;

    location / {
        proxy_pass http://127.0.0.1:8000;
    }

    location /login {
        limit_req zone=login burst=5 nodelay;
        limit_req_status 429;
        proxy_pass http://127.0.0.1:8000;
    }

    location /admin/ {
        allow 10.20.0.0/16;
        deny all;
        proxy_pass http://127.0.0.1:8000;
    }

    location /uploads/ {
        root /var/www/shop;
    }
}
